y":"MARKETING"}},"entry":{"default":{"path":"B","step":"NEW"},"quizDone":{"path":"D","step":"QUIZ"}},"sequences":{"B":[{"code":"M1","next":{"minutes":5}},{"code":"M2","next":{"hours":3},"thenPath":"C"}],"C":[{"code":"M3","next":{"days":1,"at":"10:00"}},{"code":"M4","next":{"days":2,"at":"10:00"}},{"code":"M5","next":{"days":4,"at":"10:00"}},{"code":"M6","next":{"days":14},"thenPath":"L"}],"D":[{"code":"M7","next":{"days":1}},{"code":"M8","next":{"days":2}},{"code":"M9","next":{"days":14},"thenPath":"L"}],"G":[{"code":"M12","next":{"days":3}},{"code":"M13","next":{"days":5}},{"code":"M14","next":{"days":11}},{"code":"M15","next":{"days":14},"thenPath":"L"}],"L":[]},"quizUpgrade":{"fromPaths":["B","C"],"to":{"path":"D","step":"QUIZ"}},"meeting":{"booked":"M10","reminder":"M10R","noShow":"M11","after":{"path":"G","step":"MET","next":{"days":2,"at":"10:00"}},"noShowLimit":2,"holdPath":"L"},"rules":{"onePerDayPaths":["C","D","G"],"sameDayAllowed":["M2","M3","M7"],"holdDays":14},"links":{"q":"https://refi.excelentfinance.com/?utm_source=whatsapp&utm_medium=funnel&utm_campaign=refi_funnel#check","c":"https://calendly.com/excellnet/15min","g":"https://share.google/L6zPPGazOqwdvB1pH","m":"https://www.midrag.co.il/SpCard/Sp/94658","b":"https://www.bizreviews.co.il/provider/peled-yoram"},"handoff":{"heatAtLeast":70,"onReply":true,"onBooking":true},"kpiTargets":{"costPerPayingClient":1400,"costPerMeeting":350},"meta":{"campaignIds":["120252891592490603"],"adAccount":"287081049104797"},"groups":{"meetings":"group_mm883gr6"},"identity":{"profile":"excelent_finance","nameInMessages":"יורם פלד","contactPhone":"excelent_contact","testPhones":["excelent_contact","backup"],"approved":true,"approvedBy":"יורם","approvedAt":"2026-10-20","source":"הנחיות יורם בשיחה מ 20.10.2026"},"linkTokenExamples":["a1b2c3d4e5q"]}; const C = CFG.columns;
const norm = s => { let d = String(s || '').replace(/\D/g, ''); if (d.startsWith('0')) d = '972' + d.slice(1); return d.length >= 11 ? d : ''; };
const MONTHS = {January:1,February:2,March:3,April:4,May:5,June:6,July:7,August:8,September:9,October:10,November:11,December:12};
function israelToUtc(y, mo, d, hh, mm) {
  const guess = Date.UTC(y, mo - 1, d, hh, mm);
  const p = {}; new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jerusalem', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date(guess)).forEach(x => p[x.type] = x.value);
  const off = Date.UTC(+p.year, +p.month - 1, +p.day, +(p.hour === '24' ? 0 : p.hour), +p.minute) - guess;
  return guess - off;
}
function parse(subject, text) {
  const t = String(text || '').replace(/\s+/g, ' ');
  const kind = /^(New Event|TEST New Event)/i.test(subject) ? 'new' : /^(Canceled|Cancelled)/i.test(subject) ? 'cancel' : '';
  if (!kind) return null;
  const name = (t.match(/Invitee: (.+?) Invitee Email:/) || [])[1] || '';
  const email = ((t.match(/Invitee Email: ([^\s\[]+)/) || [])[1] || '').toLowerCase();
  const dm = t.match(/Event Date\/Time: (\d{1,2}):(\d{2})\s*(am|pm)?\s*-?[^,]*, (\d{1,2}) ([A-Za-z]+) (\d{4}) \(Israel Time\)/i);
  const loc = (t.match(/Location: (\+?[\d\s\-]{9,20})/) || [])[1] || '';
  const phoneQ = (t.match(/(\+?972[\d\s\-]{8,14}|05\d[\d\s\-]{7,10})/) || [])[1] || '';
  if (!dm) return null;
  let hh=+dm[1];const mm=+dm[2],day=+dm[4],mo=MONTHS[dm[5]],year=+dm[6];
  if(!mo||mm>59||(dm[3]?(hh<1||hh>12):hh>23))return null;
  if(dm[3])hh=hh%12+(dm[3].toLowerCase()==='pm'?12:0);
  const check=new Date(Date.UTC(year,mo-1,day));
  if(check.getUTCFullYear()!==year||check.getUTCMonth()!==mo-1||check.getUTCDate()!==day)return null;
  const at = israelToUtc(year,mo,day,hh,mm);
  return { kind, name, email, phone: norm(loc) || norm(phoneQ), at };
}
const sd = $getWorkflowStaticData('global'); sd.seen = sd.seen || {};
const mails = [];
try { const b = $('Run test').first().json.body; if (b && b.subject) mails.push({ id: 'test-' + (b.id || Date.now()), subject: b.subject, text: b.text }); } catch (e) {}
try { for (const m of $('Calendly mails').all()) if (m.json && m.json.id) mails.push({ id: m.json.id, subject: m.json.subject || m.json.headers?.subject || '', text: m.json.text || m.json.snippet || '' }); } catch (e) {}
const items = $('Items').first().json.data.boards[0].items_page.items;
const out = [];
const inBatch=new Set();
for (const mail of mails) {
  if (sd.seen[mail.id]||inBatch.has(mail.id)) continue;
  inBatch.add(mail.id);
  const ev = parse(mail.subject, mail.text);
  if (!ev) continue;
  const matches=[];
  for (const it of items) {
    const cv = {}; for (const c of it.column_values) cv[c.id] = c;
    if ((ev.phone && norm(cv[C.phone]?.text) === ev.phone) || (ev.email && (cv[C.email]?.text || '').toLowerCase() === ev.email)) matches.push(it);
  }
  // Conflicting identities and duplicate owners require manual resolution.
  if(matches.length>1||(!ev.phone&&!ev.email))continue;
  const lead=matches[0]||null;
  if (!lead && ev.kind === 'cancel') continue; // a cancel for someone we do not know creates nothing
  const cv=Object.fromEntries((lead?.column_values||[]).map(c=>[c.id,c]));
  if(cv[C.stage]?.text===CFG.stages.paid)continue;
  if(ev.kind==='cancel'&&cv[C.meeting]?.value){
    let mt;try{mt=JSON.parse(cv[C.meeting].value);}catch(e){continue;}
    if(mt?.date&&Date.parse(mt.date+'T'+(mt.time||'00:00:00')+'Z')!==ev.at)continue;
  }
  const d = new Date(ev.at).toISOString();
  const cols = ev.kind === 'new'
    ? { [C.stage]: { label: CFG.stages.booked }, [C.meeting]: { date: d.slice(0, 10), time: d.slice(11, 19) } }
    : { [C.stage]: { label: CFG.stages.noShow[0] }, [C.meeting]: {} };
  if (ev.email) cols[C.email] = { email: ev.email, text: ev.email };
  out.push({ json: { kind: ev.kind, matched: !!lead, itemId: lead ? lead.id : null, name: ev.name, phone: ev.phone, colsJson: JSON.stringify(cols), mailId: mail.id } });
}
// keep the dedupe store small
const cutoff = Date.now() - 30 * 86400000; for (const k of Object.keys(sd.seen)) if (sd.seen[k] < cutoff) delete sd.seen[k];
return out;

// Acknowledge only after the final Monday write. This cache is not a durable lock.
const r=$json||{};
const id=r.data?.change_multiple_column_values?.id;
if(r.errors?.length||!id)throw new Error('Calendly write not confirmed; mail remains retryable');
const mail=$('Match bookings').item.json;
if(mail.itemId&&String(id)!==String(mail.itemId))throw new Error('Calendly write target mismatch');
const sd=$getWorkflowStaticData('global');sd.seen=sd.seen||{};sd.seen[mail.mailId]=Date.now();
return {json:{saved:true,itemId:String(id),mailId:mail.mailId}};

// n8n Code node "Items": validate every page before any attribution or write.
const pages = $input.all();
if (!pages.length) throw new Error('Monday returned no pages');
const items = [], ids = new Set(), cursors = new Set();
let me;
for (let i = 0; i < pages.length; i++) {
  const body = pages[i].json;
  if (body.errors?.length) throw new Error('Monday GraphQL errors: refusing partial results');
  const data = body.data;
  const page = data?.boards?.[0]?.items_page;
  if (!data?.me?.id || !Array.isArray(page?.items) || !Object.hasOwn(page, 'cursor') ||
      (page.cursor !== null && (typeof page.cursor !== 'string' || !page.cursor))) {
    throw new Error('Invalid Monday page');
  }
  if (me && me.id !== data.me.id) throw new Error('Monday identity changed between pages');
  me = data.me;
  if (i < pages.length - 1 && !page.cursor) throw new Error('Unexpected page after terminal cursor');
  if (page.cursor && cursors.has(page.cursor)) throw new Error('Repeated Monday cursor');
  if (page.cursor) cursors.add(page.cursor);
  if (i === pages.length - 1 && page.cursor) throw new Error('Monday result truncated at pagination limit');
  for (const item of page.items) {
    if (!item.id || !Array.isArray(item.column_values) || ids.has(String(item.id))) {
      throw new Error('Invalid or duplicate Monday item across pages');
    }
    ids.add(String(item.id)); items.push(item);
  }
}
return [{json:{data:{me,boards:[{items_page:{items,cursor:null}}]}}}];
